import{_ as t,o as d,c as o,ae as r}from"./chunks/framework.C4zpkcTP.js";const h=JSON.parse('{"title":"Results","description":"Field reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started.","frontmatter":{"title":"Results","description":"Field reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started."},"headers":[],"relativePath":"node-myanmar-payments/references/results.md","filePath":"node-myanmar-payments/references/results.md"}'),a={name:"node-myanmar-payments/references/results.md"};function c(n,e,s,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p>Starting a payment returns one of four classes exported from <code>@laranex/myanmar-payments</code>. Each has a read-only <code>flow</code> property, and <code>PaymentResult</code> is their union, so a <code>switch</code> on <code>payment.flow</code> tells them apart. Fields a gateway did not provide are <code>undefined</code>.</p><h2 id="redirectpayment" tabindex="-1">RedirectPayment <a class="header-anchor" href="#redirectpayment" aria-label="Permalink to &quot;RedirectPayment&quot;">​</a></h2><p>Returned by <code>kbz.pwa()</code> and <code>wave.initiate()</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>&#39;redirect&#39;</code></td><td><code>PaymentFlow.Redirect</code></td></tr><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID, as sent to the gateway</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td>The gateway page to redirect the customer to</td></tr><tr><td><code>gatewayReference</code></td><td><code>string | undefined</code></td><td>The gateway&#39;s ID for this attempt (KBZ <code>prepay_id</code>, Wave <code>transaction_id</code>)</td></tr><tr><td><code>raw</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>The gateway&#39;s response, for logging</td></tr></tbody></table><h2 id="formpayment" tabindex="-1">FormPayment <a class="header-anchor" href="#formpayment" aria-label="Permalink to &quot;FormPayment&quot;">​</a></h2><p>Returned by <code>aya.initiate()</code> and <code>cs.initiate()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>&#39;form&#39;</code></td><td><code>PaymentFlow.Form</code></td></tr><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>action</code></td><td><code>string</code></td><td>The gateway URL the form posts to</td></tr><tr><td><code>fields</code></td><td><code>readonly FormField[]</code></td><td>The signed hidden fields (<code>{ name, value }</code>) in order. Post them unchanged</td></tr><tr><td><code>enctype</code></td><td><code>string</code></td><td>The encoding the gateway expects; <code>application/x-www-form-urlencoded</code> unless the gateway needs another (AYA: <code>multipart/form-data</code>)</td></tr><tr><td><code>toHtml()</code></td><td><code>string</code></td><td>A complete, escaped page that submits the form on load</td></tr><tr><td><code>field(name)</code></td><td><code>string | undefined</code></td><td>One field&#39;s value</td></tr><tr><td><code>values()</code></td><td><code>Record&lt;string, string&gt;</code></td><td>The fields as an object</td></tr></tbody></table><p><code>FormField</code> is <code>{ readonly name: string; readonly value: string }</code>.</p><h2 id="qrpayment" tabindex="-1">QrPayment <a class="header-anchor" href="#qrpayment" aria-label="Permalink to &quot;QrPayment&quot;">​</a></h2><p>Returned by <code>kbz.qr()</code>, <code>yoma.initiate()</code> and <code>yoma.renewQr()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>&#39;qr&#39;</code></td><td><code>PaymentFlow.Qr</code></td></tr><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>qrString</code></td><td><code>string | undefined</code></td><td>A QR payload to encode yourself (KBZ Pay)</td></tr><tr><td><code>qrImage</code></td><td><code>string | undefined</code></td><td>A base64 image to display as is (Yoma MMQR)</td></tr><tr><td><code>expiresAt</code></td><td><code>Date | undefined</code></td><td>When the QR stops being payable; <code>undefined</code> when the gateway sets no limit</td></tr><tr><td><code>reference</code></td><td><code>string | undefined</code></td><td>The gateway&#39;s ID for this QR, used for status checks (Yoma <code>refLabel</code>, KBZ <code>prepay_id</code>)</td></tr><tr><td><code>raw</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>qrImageDataUri(mimeType?)</code></td><td><code>string | undefined</code></td><td><code>qrImage</code> as a data URI; <code>mimeType</code> defaults to <code>image/png</code>. <code>undefined</code> when there is no image</td></tr></tbody></table><h2 id="apppayment" tabindex="-1">AppPayment <a class="header-anchor" href="#apppayment" aria-label="Permalink to &quot;AppPayment&quot;">​</a></h2><p>Returned by <code>kbz.app()</code>. <code>JSON.stringify(payment)</code> writes <code>orderId</code>, <code>orderInfo</code>, <code>sign</code> and <code>signType</code>, the names the KBZ Pay SDK uses.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>&#39;app&#39;</code></td><td><code>PaymentFlow.App</code></td></tr><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>orderInfo</code></td><td><code>string</code></td><td>The signed order string the SDK expects</td></tr><tr><td><code>sign</code></td><td><code>string</code></td><td>The signature of <code>orderInfo</code></td></tr><tr><td><code>signType</code></td><td><code>string</code></td><td>The signature algorithm, <code>SHA256</code></td></tr><tr><td><code>raw</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>The gateway&#39;s response; left out of <code>toJSON()</code></td></tr><tr><td><code>toJSON()</code></td><td><code>{ orderId, orderInfo, sign, signType }</code></td><td><code>{&quot;orderId&quot;, &quot;orderInfo&quot;, &quot;sign&quot;, &quot;signType&quot;}</code>, the values your app needs</td></tr></tbody></table><h2 id="paymentflow" tabindex="-1">PaymentFlow <a class="header-anchor" href="#paymentflow" aria-label="Permalink to &quot;PaymentFlow&quot;">​</a></h2><p>A string union, so <code>payment.flow === &#39;redirect&#39;</code> works too.</p><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>Class</th></tr></thead><tbody><tr><td><code>PaymentFlow.Redirect</code></td><td><code>redirect</code></td><td><code>RedirectPayment</code></td></tr><tr><td><code>PaymentFlow.Form</code></td><td><code>form</code></td><td><code>FormPayment</code></td></tr><tr><td><code>PaymentFlow.Qr</code></td><td><code>qr</code></td><td><code>QrPayment</code></td></tr><tr><td><code>PaymentFlow.App</code></td><td><code>app</code></td><td><code>AppPayment</code></td></tr></tbody></table><p><code>PaymentFlow</code> is also a type: <code>&#39;redirect&#39; | &#39;form&#39; | &#39;qr&#39; | &#39;app&#39;</code>.</p><p><code>raw</code> values are plain JavaScript values, with JSON numbers kept as their exact text in a <code>string</code> (<code>1000.50</code> stays <code>&quot;1000.50&quot;</code>), never a rounded <code>number</code>. <code>JSON.stringify(payment.raw)</code> logs them.</p><p>Every result class takes its fields as an object, so you can build one in your own tests, e.g. <code>new RedirectPayment({ orderId: &#39;ORDER_1&#39;, url: &#39;https://…&#39; })</code>.</p>',21)])])}const y=t(a,[["render",c]]);export{h as __pageData,y as default};
